function s(t,n,r=.5){if(!t||!Number.isFinite(n)||n<=0)return!1;const a=n*Math.max(0,r);return t.bottom>=-a&&t.top<=n+a}function o(t,n=0){const r=Number.isFinite(n)?n:0;return t.map(({marker:a,button:i})=>{const e=a.getBoundingClientRect();return{button:i,left:e.left-r,top:e.top-r,width:e.width+r*2,height:e.height+r*2}})}function u(t,n){const r=Number.isFinite(t)&&t>0?t:1;return n?Math.min(r,2):r}export{u as g,s as i,o as r};
